  KEY `idx_warehouse_product` (`warehouse_id`,`product_id`),
  KEY `idx_doc_id` (`doc_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='库存台账表';
